        tuningPotential: [ { stage: "Stage 1", power: "400 - 415 hp", notes: "A software flash yields astronomical gains by unlocking the artificial 272hp electronic limiter set by Audi for the Q7.", zeroToHundred: "6.2s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "445 - 460 hp", notes: "Requires supercharger drive pulley upgrade and a massive front heat exchanger to combat extreme thermal soak.", zeroToHundred: "5.8s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Dual Pulley)", power: "510 - 540 hp", notes: "Combines an oversized crank pulley with the smaller supercharger pulley to max out Eaton rotor RPM. Requires gutted catalytic converters.", zeroToHundred: "5.3s", hundredToTwoHundred: "N/A" } ],
