        recommendedParts: { description: "Preventative maintenance of the critical 'valley components' under the supercharger is absolutely vital to longevity.", parts: [ { category: "Upper Chain Tensioners", brand: "INA", note: "CRITICAL: Replace instantly if cold-start rattling occurs to prevent chain jump." }, { category: "PCV Separator Valve", brand: "Genuine Audi", note: "Proactive replacement prevents vacuum leaks and saves the rear main seal." }, { category: "Main Thermostat", brand: "BorgWarner", note: "Replace alongside PCV to prevent catastrophic, rapid engine overheating." }, { category: "Mechanical Water Pump", brand: "Hepu", note: "Features a vastly superior metal impeller compared to the factory plastic." }, { category: "Supercharger Belt", brand: "Continental", note: "Inspect meticulously for micro-cracking; drives the heavy blower rotors." }, { category: "Ignition Coils", brand: "Eldor", note: "R8 red-top variants cure high-RPM misfires associated with aging coils." }, { category: "Spark Plugs", brand: "NGK", note: "Replace strictly every 60k km to prevent extreme coil strain." }, { category: "Oil Filter", brand: "Mann-Filter", note: "The absolute best defense against microscopic timing chain tensioner wear." } ] },
