        tuningPotential: [ { stage: "Stage 1", power: "400 - 415 hp", notes: "A software flash yields astronomical gains by completely unlocking the artificial 280hp electronic limiter set by Audi.", zeroToHundred: "6.1s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "445 - 460 hp", notes: "Requires a supercharger drive pulley upgrade and a massive front heat exchanger to combat extreme thermal soak.", zeroToHundred: "5.7s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Dual Pulley)", power: "510 - 540 hp", notes: "Combines an oversized crank pulley with the smaller supercharger pulley to max out the Eaton rotor RPM. Requires gutted catalytic converters.", zeroToHundred: "5.2s", hundredToTwoHundred: "N/A" } ],
