        tuningPotential: [ { stage: "Stage 1", power: "290 - 300 hp", notes: "An EDC17 software flash unlocks the CCMA, adding massive torque. It drastically improves towing capability and highway passing while overriding artificial detuning.", zeroToHundred: "7.6s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "315 - 330 hp", notes: "Requires deleting the DPF, EGR, and restrictive SCR/AdBlue systems (where legally permitted). Provides incredible mid-range punch.", zeroToHundred: "7.2s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Hybrid Turbo)", power: "360 - 390 hp", notes: "Requires a bolt-on hybrid VNT turbocharger, CP3 pump conversion to replace the fragile CP4, and an upgraded intercooler. Turns the heavy SUV into a genuine diesel locomotive.", zeroToHundred: "6.4s", hundredToTwoHundred: "N/A" } ],
