        tuningPotential: [ { stage: "Stage 1", power: "295 - 310 hp", notes: "Because the CJMA is heavily detuned from the factory for efficiency, an EDC17 software flash absolutely transforms the vehicle. It adds an unbelievable 100hp and 150Nm safely.", zeroToHundred: "7.4s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "320 - 340 hp", notes: "Requires completely gutting the DPF and blanking the EGR. Provides incredible mid-range punch and lowers EGTs significantly.", zeroToHundred: "6.9s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Hybrid Turbo)", power: "380 - 410 hp", notes: "Requires a bolt-on hybrid VNT turbocharger, CP3 pump conversion to replace the fragile CP4.2, and an upgraded intercooler. Turns the heavy SUV into a genuine diesel locomotive.", zeroToHundred: "6.1s", hundredToTwoHundred: "N/A" } ],
