        tuningPotential: [ { stage: "Stage 1", power: "300 - 315 hp", notes: "An EDC17 software flash safely adds massive power, bringing torque over 650Nm. Transforms the towing capability and completely removes initial throttle lag.", zeroToHundred: "7.1s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "325 - 345 hp", notes: "Requires completely gutting the DPF and blanking the EGR. Provides incredible mid-range punch and lowers EGTs significantly.", zeroToHundred: "6.7s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Hybrid Turbo)", power: "390 - 430 hp", notes: "Requires a bolt-on hybrid VNT turbocharger, CP3 pump conversion to replace the fragile CP4.2, and an upgraded intercooler. Turns the heavy SUV into a genuine diesel locomotive.", zeroToHundred: "5.9s", hundredToTwoHundred: "N/A" } ],
