        tuningPotential: [ { stage: "Stage 1", power: "390 - 405 hp", notes: "A software flash completely transforms the CCFC, unlocking over 920Nm of torque. The massive ZF 8HP90 handles this effortlessly.", zeroToHundred: "5.4s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "420 - 440 hp", notes: "Requires completely gutting the dual DPFs and blanking both EGRs. Provides incredible mid-range punch and drastically lowers EGTs.", zeroToHundred: "5.0s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Hybrid Turbos)", power: "500 - 530 hp", notes: "Requires twin bolt-on hybrid VNT turbochargers, upgraded dual intercoolers, and high-pressure fuel pump upgrades. Turns the SUV into an unstoppable diesel locomotive.", zeroToHundred: "4.5s", hundredToTwoHundred: "N/A" } ],
